 "content": "from collections import Counter


def transform(grid):
    """Count horizontal bars of the two foreground colors and pack them into 2x3."""
    counts = Counter(cell for row in grid for cell in row)
    background = counts.most_common(1)[0][0]
    bars = Counter()
    for row in grid:
        i = 0
        while i < len(row):
            color = row[i]
            if color == background:
                i += 1
                continue
            bars[color] += 1
            while i < len(row) and row[i] == color:
                i += 1
    colors = [color for color in sorted(bars)]
    values = []
    for color in colors:
        values.extend([color] * bars[color])
    values = (values + [0] * 6)[:6]
    return [values[:3], values[3:]]
